// an icon by its name ("level", "mod-pedal"); nullptr if there is none
inline const Icon* find(const char* name, size_t len) {
	for (const Icon& i : kIcons)
		if (std::strlen(i.name) == len && std::strncmp(i.name, name, len) == 0) return &i;
	return nullptr;
}

